def edit_distance(source, target):
    n = len(source)
    m = len(target)
    table = []
    for i in range(n + 1):
        row = []
        for j in range(m + 1):
            row.append(0)
        table.append(row)
    for i in range(n + 1):
        table[i][0] = i
    for j in range(m + 1):
        table[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if source[i-1] == target[j-1]:
                cost = 0
            else:
                cost = 2
            del_val = table[i-1][j] + 1
            ins_val = table[i][j-1] + 1
            sub_val = table[i-1][j-1] + cost
            if del_val <= ins_val and del_val <= sub_val:
                table[i][j] = del_val
            elif ins_val <= del_val and ins_val <= sub_val:
                table[i][j] = ins_val
            else:
                table[i][j] = sub_val
    return table[n][m]
def closest(word, dictionary):
    best_word = ""
    min_dist = 9999
    for item in dictionary:
        d = edit_distance(word, item)
        if d < min_dist:
            min_dist = d
            best_word = item
    return best_word
print(edit_distance("intention", "execution"))

